def tiled_gemm_reference(a, b, tile=32):
    m, k = a.shape
    kb, n = b.shape
    assert k == kb
    c = a.new_zeros((m, n))
    for i in range(0, m, tile):
        for j in range(0, n, tile):
            for p in range(0, k, tile):
                c[i:i+tile, j:j+tile] += a[i:i+tile, p:p+tile] @ b[p:p+tile, j:j+tile]
    return c
